  onAccess(key: K, value: V): void
  onInsert(key: K, value: V): void
  evict(container: Map<K,V>): void
}

class Registry<K,V> {
  private map = new Map<string, EvictionStrategy<K,V>>();
  register(name: string, s: EvictionStrategy<K,V>) { this.map.set(name, s) }
  get(name: string): EvictionStrategy<K,V> | undefined { return this.map.get(name) }
}
